update fund_order_record set is_rollback=true
where record_id=#{recordId} and account_id=#{accountId}
and now() > able_rollback_time and is_pay=true and is_rollback=false and is_refund=false

update fund_order_record set is_refund=true
where order_id=#{orderId} and account_id=#{accountId}
and now() > able_rollback_time and is_pay=true and is_rollback=true and is_refund=false
